//! Replays the Pi 1.3.0 `navigateTree` traces in
//! `docs/provider-parity/tree-reference.json` (regenerated by
//! `check-tree-reference.mjs`) through the harness and compares hook events,
//! session mutations, the final leaf and the result. The only projection is
//! the generated summary entry ID, which the reference fixture names `summary`.
use std::sync::{Arc, Mutex};

use rpi_agent::message::CustomMessage;
use rpi_agent::AgentMessage;
use rpi_ai::identity::RequestIdentity;
use rpi_ai::providers::faux::{faux_assistant_message, FauxProvider, FauxScript};
use rpi_ai::types::{Content, StopReason, UserContent, UserMessage};
use rpi_ai::{Provider, ProviderHooks};
use rpi_harness::agent_harness::{AgentHarness, AgentLane, NavigateTreeOptions, NavigationOutcome};
use rpi_harness::session::memory::{InMemorySessionStorage, SystemClock};
use rpi_harness::session::types::{ProvisionedEntry, ProvisionedKind, SessionMetadata};
use rpi_harness::session::{DefaultIdGenerator, Session};
use rpi_harness::types::AgentHarnessOptions;
use serde_json::{json, Value};
use tokio_util::sync::CancellationToken;

struct Hooks {
    mode: String,
    events: Mutex<Vec<Value>>,
    failures: Mutex<Vec<(Value, RequestIdentity)>>,
    identities: Mutex<Vec<RequestIdentity>>,
}

#[async_trait::async_trait]
impl ProviderHooks for Hooks {
    async fn lifecycle(
        &self,
        event: &str,
        data: Value,
        identity: RequestIdentity,
        signal: CancellationToken,
    ) -> Result<Option<Value>, String> {
        if event == "session_tree_failed" {
            self.failures.lock().unwrap().push((data, identity));
            return Ok(None);
        }
        self.identities.lock().unwrap().push(identity);
        if event != "session_before_tree" {
            let mut recorded = json!({"type": event});
            for (key, value) in data.as_object().unwrap() {
                recorded[key] = value.clone();
            }
            self.events.lock().unwrap().push(recorded);
            return Ok(None);
        }
        assert!(!signal.is_cancelled());
        let mut preparation = data["preparation"].clone();
        preparation["entriesToSummarize"] = preparation["entriesToSummarize"]
            .as_array()
            .unwrap()
            .iter()
            .map(|entry| entry["id"].clone())
            .collect();
        self.events
            .lock()
            .unwrap()
            .push(json!({"type": event, "preparation": preparation}));
        Ok(match self.mode.as_str() {
            "cancel" => Some(json!({"cancel": true})),
            "hookError" => return Err("fixture hook failure".into()),
            "override" | "ignoredOverride" => Some(json!({
                "summary": {"summary": "retained summary", "details": {"fixture": true}},
                "label": "summary label"})),
            "overrideLabel" => Some(json!({"customInstructions": "new instructions",
                "replaceInstructions": true, "label": "changed"})),
            _ => None,
        })
    }
}

fn message(id: &str, message: AgentMessage) -> ProvisionedEntry {
    ProvisionedEntry {
        id: id.into(),
        kind: ProvisionedKind::Message {
            message,
            terminate: None,
        },
    }
}

fn user(text: &str) -> AgentMessage {
    AgentMessage::User(UserMessage::new(
        UserContent::Blocks(vec![Content::text(text)]),
        0,
    ))
}

fn assistant(text: &str) -> AgentMessage {
    AgentMessage::Assistant(Box::new(faux_assistant_message(text, StopReason::Stop)))
}

/// The reference tree: `root` with children `left` (the old leaf), `target`,
/// `user` and the custom message `custom`.
async fn fixture_harness(hooks: Arc<Hooks>) -> AgentHarness {
    fixture_harness_with(hooks, FauxScript::new().with_text("unused")).await
}

async fn fixture_harness_with(hooks: Arc<Hooks>, script: FauxScript) -> AgentHarness {
    let provider = FauxProvider::new(script);
    let storage = Arc::new(InMemorySessionStorage::new(
        SessionMetadata {
            id: "tree".into(),
            created_at: 0,
            parent_session_id: None,
        },
        Arc::new(SystemClock),
        Arc::new(DefaultIdGenerator::new()),
    ));
    let session = Session::new(storage, None);
    let harness = AgentHarness::create(AgentHarnessOptions {
        model: provider.default_model().clone(),
        thinking_level: Default::default(),
        active_tool_names: Vec::new(),
        tools: Vec::new(),
        system_prompt: None,
        resources: Default::default(),
        stream_options: Default::default(),
        retry: Default::default(),
        compaction: Default::default(),
        steering_mode: Default::default(),
        follow_up_mode: Default::default(),
        tool_execution: Default::default(),
        drive: Default::default(),
        session,
        models: vec![provider.clone() as Arc<dyn Provider>],
        to_provider_messages: None,
        entry_projectors: Default::default(),
        agent_emitter: None,
        before_tool_call: None,
        after_tool_call: None,
        transform_context: None,
        entry_transforms: Vec::new(),
        provider_hooks: Some(hooks),
        allow_existing_session: false,
    })
    .await
    .unwrap();
    let session = harness.session();
    session
        .append_entry(message("root", user("root prompt")), "main")
        .await
        .unwrap();
    for entry in [
        message("left", assistant("abandoned")),
        message("target", assistant("target response")),
        message("user", user("edit this")),
        message(
            "custom",
            AgentMessage::Custom(CustomMessage::new(
                "custom",
                vec![Content::text("edit custom")],
                json!({"customType": "fixture", "display": true}),
                0,
            )),
        ),
    ] {
        session.move_lane("main", Some("root")).await.unwrap();
        session.append_entry(entry, "main").await.unwrap();
    }
    session.move_lane("main", Some("left")).await.unwrap();
    harness
}

/// The reference's session-manager view of a branch summary entry.
fn summary_view(entry: &Value, summary_id: &str) -> Value {
    let mut view = json!({});
    for key in [
        "type", "id", "parentId", "fromId", "summary", "details", "fromHook",
    ] {
        if let Some(value) = entry.get(key) {
            view[key] = value.clone();
        }
    }
    if view["id"] == summary_id {
        view["id"] = json!("summary");
    }
    view
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn navigation_matches_pi_reference_traces() {
    let reference: Value = serde_json::from_str(include_str!(
        "../../../docs/provider-parity/tree-reference.json"
    ))
    .unwrap();
    let rows = reference["rows"].as_array().unwrap();
    assert_eq!(rows.len(), 10);
    for row in rows {
        let mode = row["mode"].as_str().unwrap();
        let hooks = Arc::new(Hooks {
            mode: mode.into(),
            events: Mutex::new(Vec::new()),
            failures: Mutex::new(Vec::new()),
            identities: Mutex::new(Vec::new()),
        });
        let harness = fixture_harness(hooks.clone()).await;
        let target = match mode {
            "same" => "left",
            "missing" => "absent",
            "user" => "user",
            "custom" => "custom",
            _ => "target",
        };
        let navigated = harness
            .navigate_tree_with(
                Some(target),
                NavigateTreeOptions {
                    summarize: mode == "override",
                    custom_instructions: Some("original".into()),
                    replace_instructions: None,
                    label: Some("original label".into()),
                },
            )
            .await
            .unwrap();

        let session = harness.session();
        let summary = match &navigated.outcome {
            NavigationOutcome::Completed {
                summary_entry: Some(entry),
                ..
            } => Some(serde_json::to_value(entry).unwrap()),
            _ => None,
        };
        let summary_id = summary
            .as_ref()
            .map(|entry| entry["id"].as_str().unwrap().to_owned())
            .unwrap_or_default();
        let rename = |id: Value| {
            if id == summary_id.as_str() {
                json!("summary")
            } else {
                id
            }
        };

        let mut events = hooks.events.lock().unwrap().clone();
        for event in &mut events {
            if let Some(entry) = event.get("summaryEntry").cloned() {
                event["summaryEntry"] = summary_view(&entry, &summary_id);
            }
            if let Some(id) = event.get("newLeafId").cloned() {
                event["newLeafId"] = rename(id);
            }
        }
        assert_eq!(Value::Array(events), row["events"], "{mode}: events");

        let leaf = session.get_leaf_id().await.unwrap();
        let mut mutations = Vec::new();
        match &summary {
            Some(entry) => mutations.push(summary_view(entry, &summary_id)),
            None if leaf.as_deref() != Some("left") => {
                mutations.push(json!({"type": "branch", "id": leaf}));
            }
            None => {}
        }
        let mut labelled: Vec<String> = ["root", "left", "target", "user", "custom"]
            .iter()
            .map(|id| id.to_string())
            .collect();
        labelled.push(summary_id.clone());
        for id in labelled.iter().filter(|id| !id.is_empty()) {
            if let Some(label) = session.get_label(id).await.unwrap() {
                mutations.push(json!({"type": "label", "id": rename(json!(id)), "label": label}));
            }
        }
        assert_eq!(Value::Array(mutations), row["mutations"], "{mode}: mutations");
        assert_eq!(rename(json!(leaf)), row["leaf"], "{mode}: leaf");

        let mut result = json!({});
        match &navigated.outcome {
            NavigationOutcome::Completed { editor_text, .. } => {
                result["cancelled"] = json!(false);
                if let Some(text) = editor_text {
                    result["editorText"] = json!(text);
                }
                if let Some(entry) = &summary {
                    result["summaryEntry"] = summary_view(entry, &summary_id);
                }
                assert_eq!(result, row["result"], "{mode}: result");
            }
            NavigationOutcome::Declined { .. } => {
                assert_eq!(json!({"cancelled": true}), row["result"], "{mode}: result");
            }
            NavigationOutcome::Aborted { .. } => {
                assert_eq!(
                    json!({"cancelled": true, "aborted": true}),
                    row["result"],
                    "{mode}: result"
                );
            }
            NavigationOutcome::Failed { error, .. } => {
                assert_eq!(json!(error.message), row["error"], "{mode}: error");
            }
        }

        // Every hook shares the navigation's operation identity.
        for identity in hooks.identities.lock().unwrap().iter() {
            assert_eq!(identity.operation_id, navigated.run_id, "{mode}");
            assert_eq!(identity.purpose, "tree", "{mode}");
            assert_eq!(identity.session_id.as_deref(), Some("tree"), "{mode}");
        }
        // The native terminal fires exactly when Pi emits a before event without
        // `session_tree`, so an operation started by the before hook always ends.
        let began = row["events"].as_array().unwrap().iter().any(|e| e["type"] == "session_before_tree");
        let finished = row["events"].as_array().unwrap().iter().any(|e| e["type"] == "session_tree");
        let failures = hooks.failures.lock().unwrap().clone();
        assert_eq!(failures.len(), usize::from(began && !finished), "{mode}: terminal");
        for (payload, identity) in failures {
            assert_eq!(identity.operation_id, navigated.run_id);
            assert_eq!(payload["cancelled"], mode == "cancel", "{mode}");
            assert_eq!(payload["aborted"], false, "{mode}");
            if mode == "hookError" {
                assert_eq!(payload["error"], "fixture hook failure");
            }
        }
    }
}

/// The default summarizer path that the reference fixture leaves to
/// `branch-summary-reference.json`: a generated summary lands on the target,
/// carries file details and `fromHook: false`, and takes the label.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn default_summary_is_attached_at_the_target_and_cancellation_aborts() {
    for mode in ["summarize", "abort"] {
        let hooks = Arc::new(Hooks {
            mode: "none".into(),
            events: Mutex::new(Vec::new()),
            failures: Mutex::new(Vec::new()),
            identities: Mutex::new(Vec::new()),
        });
        let script = FauxScript::new().with_text("unused");
        // Slow enough that the abort below always lands mid-summary.
        let script = if mode == "abort" { script.with_tokens_per_second(1.0) } else { script };
        let harness = fixture_harness_with(hooks.clone(), script).await;
        let navigation = harness.navigate_tree_with(
            Some("target"),
            NavigateTreeOptions {
                summarize: true,
                custom_instructions: None,
                replace_instructions: None,
                label: Some("kept".into()),
            },
        );
        let navigated = if mode == "abort" {
            // Abort while the summary is being generated.
            let lane = harness.clone();
            let abort = async move {
                tokio::time::sleep(std::time::Duration::from_millis(200)).await;
                lane.abort().await.ok();
            };
            let (navigated, ()) = tokio::join!(navigation, abort);
            navigated.unwrap()
        } else {
            navigation.await.unwrap()
        };
        let session = harness.session();
        match (mode, &navigated.outcome) {
            ("summarize", NavigationOutcome::Completed { summary_entry: Some(entry), new_leaf_id, editor_text: None }) => {
                let entry = serde_json::to_value(entry).unwrap();
                assert_eq!(entry["type"], "branch_summary");
                assert_eq!(entry["parentId"], "target");
                assert_eq!(entry["fromId"], "left");
                assert_eq!(entry["fromHook"], false);
                assert_eq!(entry["details"], json!({"readFiles": [], "modifiedFiles": []}));
                assert!(entry["summary"].as_str().unwrap().ends_with("unused"));
                assert_eq!(new_leaf_id.as_deref(), entry["id"].as_str());
                assert_eq!(session.get_leaf_id().await.unwrap().as_deref(), entry["id"].as_str());
                assert_eq!(session.get_label(entry["id"].as_str().unwrap()).await.unwrap().as_deref(), Some("kept"));
                assert_eq!(session.get_label("target").await.unwrap(), None);
                let events = hooks.events.lock().unwrap().clone();
                assert_eq!(events.last().unwrap()["fromExtension"], false);
            }
            ("abort", NavigationOutcome::Aborted { leaf_id }) => {
                assert_eq!(leaf_id.as_deref(), Some("left"));
                assert_eq!(session.get_leaf_id().await.unwrap().as_deref(), Some("left"));
                let failures = hooks.failures.lock().unwrap().clone();
                assert_eq!(failures.len(), 1);
                assert_eq!(failures[0].0["aborted"], true);
                assert_eq!(failures[0].0["cancelled"], true);
            }
            (mode, outcome) => panic!("{mode}: unexpected {outcome:?}"),
        }
    }
}
